const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const service_type = (raw.service_type || (raw.intent === 'GENERATE_EPISODE' ? 'GPU' : 'LLM')).toString().toUpperCase().trim();
const estimated_cost_units = Number(raw.estimated_cost_units !== undefined ? raw.estimated_cost_units : (service_type === 'GPU' ? 250 : 50));
const usage_date = $now.toISOString().slice(0, 10);

if (!project_id) {
  throw new Error('WF-12 Error: project_id is strictly required for Quota Governance (Rule 5).');
}

return { json: { ...raw, project_id, service_type, estimated_cost_units, usage_date, sessionId: (raw.sessionId || `sess_${$execution.id}`).toString() } };

const base = $('Input Normalizer & Cost Estimator').item.json;
const resp = $input.item.json;
const existingRow = Array.isArray(resp) ? resp[0] : (resp && resp.accumulated_units !== undefined ? resp : null);

const dailyLimit = Number($env.DAILY_QUOTA_LIMIT || 5000);
const currentAccumulated = Number(existingRow?.accumulated_units || 0);
const estimatedCost = Number(base.estimated_cost_units || 0);
const projectedTotal = currentAccumulated + estimatedCost;

const is_allowed = projectedTotal <= dailyLimit;
const remaining_quota = Math.max(0, dailyLimit - (is_allowed ? projectedTotal : currentAccumulated));
const quota_status = is_allowed ? 'QUOTA_APPROVED' : 'QUOTA_EXCEEDED';

return {
  json: {
    ...base, daily_quota_limit: dailyLimit, current_accumulated_units: currentAccumulated, projected_total_units: projectedTotal,
    remaining_quota_units: remaining_quota, is_allowed, quota_status,
    upsert_payload: { project_id: base.project_id, usage_date: base.usage_date, service_type: base.service_type, accumulated_units: projectedTotal, updated_at: $now.toISOString() }
  }
};

const state = $('Quota & Throttling Evaluator').item.json;

const msg = state.is_allowed
  ? [
      `✅ **WF-12: Quota Approved (${state.service_type})!**`,
      `• **Date:** \`${state.usage_date}\` | **Service:** \`${state.service_type}\``,
      `• **Used / Daily Limit:** \`${state.projected_total_units} / ${state.daily_quota_limit}\` units`,
      `• **Remaining Quota:** \`${state.remaining_quota_units}\` units`
    ].join('\n')
  : [
      `🛑 **WF-12: QUOTA_EXCEEDED (${state.service_type})!**`,
      `• **Date:** \`${state.usage_date}\` | **Current Used:** \`${state.current_accumulated_units}\` units`,
      `• **Requested Cost:** \`+${state.estimated_cost_units}\` units would exceed Daily Limit (\`${state.daily_quota_limit}\`).`,
      `• **Action:** Request throttled & blocked safely.`
    ].join('\n');

return {
  json: {
    ...state, ok: state.is_allowed, status: state.quota_status, workflow_name: 'WF-12', execution_id: $execution.id,
    is_allowed: state.is_allowed, remaining_quota: state.remaining_quota_units, output: msg, text: msg
  }
};

